-- ** CostingLine
-- | CostingLine
-- A single costing line: material cost for one BOM component.
data CostingLine = CostingLine
  { costingLineLineCost :: !(Text) -- ^ /Required/ "lineCost" - total_quantity × unit_purchase_price (0 when price unknown).
  , costingLineName :: !(Text) -- ^ /Required/ "name"
  , costingLineProductId :: !(Text) -- ^ /Required/ "productId"
  , costingLineQuantityPerUnit :: !(Integer) -- ^ /Required/ "quantityPerUnit" - Component quantity required per finished unit.
  , costingLineSku :: !(Text) -- ^ /Required/ "sku"
  , costingLineTotalQuantity :: !(Integer) -- ^ /Required/ "totalQuantity" - Total component quantity consumed by this order.
  , costingLineUnitPurchasePrice :: !(Maybe Text) -- ^ "unitPurchasePrice"
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON CostingLine
instance A.FromJSON CostingLine where
  parseJSON = A.withObject "CostingLine" $ \o ->
    CostingLine
      <$> (o .:  "lineCost")
      <*> (o .:  "name")
      <*> (o .:  "productId")
      <*> (o .:  "quantityPerUnit")
      <*> (o .:  "sku")
      <*> (o .:  "totalQuantity")
      <*> (o .:? "unitPurchasePrice")

-- | ToJSON CostingLine
instance A.ToJSON CostingLine where
  toJSON CostingLine {..} =
   _omitNulls
      [ "lineCost" .= costingLineLineCost
      , "name" .= costingLineName
      , "productId" .= costingLineProductId
      , "quantityPerUnit" .= costingLineQuantityPerUnit
      , "sku" .= costingLineSku
      , "totalQuantity" .= costingLineTotalQuantity
      , "unitPurchasePrice" .= costingLineUnitPurchasePrice
      ]


-- | Construct a value of type 'CostingLine' (by applying it's required fields, if any)
mkCostingLine
  :: Text -- ^ 'costingLineLineCost': total_quantity × unit_purchase_price (0 when price unknown).
  -> Text -- ^ 'costingLineName' 
  -> Text -- ^ 'costingLineProductId' 
  -> Integer -- ^ 'costingLineQuantityPerUnit': Component quantity required per finished unit.
  -> Text -- ^ 'costingLineSku' 
  -> Integer -- ^ 'costingLineTotalQuantity': Total component quantity consumed by this order.
  -> CostingLine
mkCostingLine costingLineLineCost costingLineName costingLineProductId costingLineQuantityPerUnit costingLineSku costingLineTotalQuantity =
