-- ** Job
-- | Job
data Job = Job
  { jobAttempts :: !(Maybe Int) -- ^ "attempts"
  , jobJobType :: !(Text) -- ^ /Required/ "jobType" - Discriminator the worker dispatches on (e.g. \&quot;webhook.deliver\&quot;).
  , jobMaxAttempts :: !(Int) -- ^ /Required/ "maxAttempts"
  , jobPayload :: !(Maybe AnyType) -- ^ "payload"
  , jobRunAt :: !(Maybe DateTime) -- ^ "runAt" - Earliest execution time; None &#x3D; run now.
  , jobStatus :: !(JobStatus) -- ^ /Required/ "status" - pending | running | done | failed
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON Job
instance A.FromJSON Job where
  parseJSON = A.withObject "Job" $ \o ->
    Job
      <$> (o .:? "attempts")
      <*> (o .:  "jobType")
      <*> (o .:  "maxAttempts")
      <*> (o .:? "payload")
      <*> (o .:? "runAt")
      <*> (o .:  "status")

-- | ToJSON Job
instance A.ToJSON Job where
  toJSON Job {..} =
   _omitNulls
      [ "attempts" .= jobAttempts
      , "jobType" .= jobJobType
      , "maxAttempts" .= jobMaxAttempts
      , "payload" .= jobPayload
      , "runAt" .= jobRunAt
      , "status" .= jobStatus
      ]


-- | Construct a value of type 'Job' (by applying it's required fields, if any)
mkJob
  :: Text -- ^ 'jobJobType': Discriminator the worker dispatches on (e.g. \"webhook.deliver\").
  -> Int -- ^ 'jobMaxAttempts' 
  -> JobStatus -- ^ 'jobStatus': pending | running | done | failed
  -> Job
mkJob jobJobType jobMaxAttempts jobStatus =
  Job
  { jobAttempts = Nothing
  , jobJobType
  , jobMaxAttempts
  , jobPayload = Nothing
  , jobRunAt = Nothing
  , jobStatus
  }

