-- ** SubscriptionOverview
-- | SubscriptionOverview
-- Tenant subscription overview for the billing page: current plan, status, period end, trial state, effective limits, current usage and feature flags. Backed by Paddle Billing webhook data written into `billing_info` + `tenants.plan`, and by the canonical plans in `crate::saasy::plans`.  JSON contract (camelCase, matches the frontend): `plan`, `planName`, `priceEur`, `status`, `currentPeriodEnd`, `manageUrl`, `trialEndsAt`, `isTrialing`, `limits:{maxUsers,maxInvoicesPerMonth,maxConnectors}`, `usage:{users,invoicesThisMonth,connectors,overageSeats}`, `features:{taxAutomations,fancyReports,erp}`.
data SubscriptionOverview = SubscriptionOverview
  { subscriptionOverviewCurrentPeriodEnd :: !(Maybe DateTime) -- ^ "currentPeriodEnd"
  , subscriptionOverviewFeatures :: !(PlanFeatures) -- ^ /Required/ "features"
  , subscriptionOverviewIsTrialing :: !(Bool) -- ^ /Required/ "isTrialing"
  , subscriptionOverviewLimits :: !(PlanLimits) -- ^ /Required/ "limits"
  , subscriptionOverviewManageUrl :: !(Maybe Text) -- ^ "manageUrl"
  , subscriptionOverviewPlan :: !(Text) -- ^ /Required/ "plan" - Resolved plan id (free/starter/business/enterprise, or a custom override id).
  , subscriptionOverviewPlanName :: !(Text) -- ^ /Required/ "planName"
  , subscriptionOverviewPriceEur :: !(Double) -- ^ /Required/ "priceEur" - Monthly price in EUR; &#x60;-1.0&#x60; &#x3D; custom pricing (enterprise).
  , subscriptionOverviewQuantity :: !(Maybe Int) -- ^ "quantity"
  , subscriptionOverviewStatus :: !(Maybe Text) -- ^ "status"
  , subscriptionOverviewSubscriptionId :: !(Maybe Text) -- ^ "subscriptionId"
  , subscriptionOverviewTrialEndsAt :: !(Maybe DateTime) -- ^ "trialEndsAt"
  , subscriptionOverviewUsage :: !(UsageSnapshot) -- ^ /Required/ "usage"
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON SubscriptionOverview
instance A.FromJSON SubscriptionOverview where
  parseJSON = A.withObject "SubscriptionOverview" $ \o ->
    SubscriptionOverview
      <$> (o .:? "currentPeriodEnd")
      <*> (o .:  "features")
      <*> (o .:  "isTrialing")
      <*> (o .:  "limits")
      <*> (o .:? "manageUrl")
      <*> (o .:  "plan")
      <*> (o .:  "planName")
      <*> (o .:  "priceEur")
      <*> (o .:? "quantity")
      <*> (o .:? "status")
      <*> (o .:? "subscriptionId")
      <*> (o .:? "trialEndsAt")
      <*> (o .:  "usage")

-- | ToJSON SubscriptionOverview
instance A.ToJSON SubscriptionOverview where
  toJSON SubscriptionOverview {..} =
   _omitNulls
      [ "currentPeriodEnd" .= subscriptionOverviewCurrentPeriodEnd
      , "features" .= subscriptionOverviewFeatures
      , "isTrialing" .= subscriptionOverviewIsTrialing
      , "limits" .= subscriptionOverviewLimits
      , "manageUrl" .= subscriptionOverviewManageUrl
      , "plan" .= subscriptionOverviewPlan
      , "planName" .= subscriptionOverviewPlanName
      , "priceEur" .= subscriptionOverviewPriceEur
      , "quantity" .= subscriptionOverviewQuantity
      , "status" .= subscriptionOverviewStatus
      , "subscriptionId" .= subscriptionOverviewSubscriptionId
      , "trialEndsAt" .= subscriptionOverviewTrialEndsAt
      , "usage" .= subscriptionOverviewUsage
      ]


