-- * Enums


-- ** AbsenceStatus

-- | Enum of 'Text' .
-- Absence request status.
data AbsenceStatus
  = AbsenceStatus'Pending -- ^ @"pending"@
  | AbsenceStatus'Approved -- ^ @"approved"@
  | AbsenceStatus'Rejected -- ^ @"rejected"@
  | AbsenceStatus'Cancelled -- ^ @"cancelled"@
  deriving (P.Show, P.Eq, P.Typeable, P.Ord, P.Bounded, P.Enum)

instance A.ToJSON AbsenceStatus where toJSON = A.toJSON . fromAbsenceStatus
instance A.FromJSON AbsenceStatus where parseJSON o = P.either P.fail (pure . P.id) . toAbsenceStatus =<< A.parseJSON o
instance WH.ToHttpApiData AbsenceStatus where toQueryParam = WH.toQueryParam . fromAbsenceStatus
instance WH.FromHttpApiData AbsenceStatus where parseQueryParam o = WH.parseQueryParam o >>= P.left T.pack . toAbsenceStatus
instance MimeRender MimeMultipartFormData AbsenceStatus where mimeRender _ = mimeRenderDefaultMultipartFormData

-- | unwrap 'AbsenceStatus' enum
fromAbsenceStatus :: AbsenceStatus -> Text
fromAbsenceStatus = \case
  AbsenceStatus'Pending -> "pending"
  AbsenceStatus'Approved -> "approved"
  AbsenceStatus'Rejected -> "rejected"
  AbsenceStatus'Cancelled -> "cancelled"

-- | parse 'AbsenceStatus' enum
toAbsenceStatus :: Text -> P.Either String AbsenceStatus
toAbsenceStatus = \case
  "pending" -> P.Right AbsenceStatus'Pending
  "approved" -> P.Right AbsenceStatus'Approved
  "rejected" -> P.Right AbsenceStatus'Rejected
  "cancelled" -> P.Right AbsenceStatus'Cancelled
  s -> P.Left $ "toAbsenceStatus: enum parse failure: " P.++ P.show s


-- ** AbsenceType

-- | Enum of 'Text' .
-- Absence type.
data AbsenceType
  = AbsenceType'Vacation -- ^ @"vacation"@
  | AbsenceType'Sick -- ^ @"sick"@
  | AbsenceType'Sabbatical -- ^ @"sabbatical"@
  | AbsenceType'Parental -- ^ @"parental"@
  | AbsenceType'Other -- ^ @"other"@
  deriving (P.Show, P.Eq, P.Typeable, P.Ord, P.Bounded, P.Enum)

instance A.ToJSON AbsenceType where toJSON = A.toJSON . fromAbsenceType
instance A.FromJSON AbsenceType where parseJSON o = P.either P.fail (pure . P.id) . toAbsenceType =<< A.parseJSON o
instance WH.ToHttpApiData AbsenceType where toQueryParam = WH.toQueryParam . fromAbsenceType
instance WH.FromHttpApiData AbsenceType where parseQueryParam o = WH.parseQueryParam o >>= P.left T.pack . toAbsenceType
instance MimeRender MimeMultipartFormData AbsenceType where mimeRender _ = mimeRenderDefaultMultipartFormData

-- | unwrap 'AbsenceType' enum
fromAbsenceType :: AbsenceType -> Text
fromAbsenceType = \case
  AbsenceType'Vacation -> "vacation"
  AbsenceType'Sick -> "sick"
  AbsenceType'Sabbatical -> "sabbatical"
  AbsenceType'Parental -> "parental"
  AbsenceType'Other -> "other"

-- | parse 'AbsenceType' enum
toAbsenceType :: Text -> P.Either String AbsenceType
