-- | parse 'WebhookEventStatus' enum
toWebhookEventStatus :: Text -> P.Either String WebhookEventStatus
toWebhookEventStatus = \case
  "accepted" -> P.Right WebhookEventStatus'Accepted
  "delivered" -> P.Right WebhookEventStatus'Delivered
  "failed" -> P.Right WebhookEventStatus'Failed
  "received" -> P.Right WebhookEventStatus'Received
  s -> P.Left $ "toWebhookEventStatus: enum parse failure: " P.++ P.show s


